using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.SportsTest;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Workshop.Editor {
public static class ChassisVerification {
 static List<string> lines=new List<string>();static void Check(bool yes,string text){lines.Add((yes?"PASS ":"FAIL ")+text);if(!yes)throw new Exception(text);}static void Reject(Action a,string text){bool no=false;try{a();}catch{no=true;}Check(no,text);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 public static void Run(){Directory.CreateDirectory("Verification/Chassis");try{
  var c=WorkshopCatalog.Load("car_finch");Check(c.offers.Length==49,"49 authored offers include 12 chassis stages");var b=new WorkshopBuild();var stock=c.Resolve(b);Check(Mathf.Abs(ChassisTuning.CrankHp(stock)-stock.PeakKw()*1.34102209f)<.0001f&&Mathf.Abs(ChassisTuning.EstimatedWhp(stock)-ChassisTuning.CrankHp(stock)*stock.efficiency)<.0001f,"HP conversion and estimated drivetrain WHP exact");
  var equal=ChassisTuning.AxleTorque(1000,700,100,1,1);Check(equal==new Vector2(500,500),"Open differential distributes equal torque");var lsd=ChassisTuning.AxleTorque(1000,700,100,4,1);Check(Mathf.Abs(lsd.x+lsd.y-1000)<.001f&&lsd.y>lsd.x&&lsd.y/lsd.x<=4.001f,"LSD transfers conserved torque toward slower wheel within bias limit");Check(!BurnoutEffects.ShouldSmoke(false,1,40,0,800,1,false)&&!BurnoutEffects.ShouldSmoke(true,1,40,0,800,1,true),"No smoke in air or locked garage");Check(BurnoutEffects.ShouldSmoke(true,.6f,25,2,800,1,false)&&!BurnoutEffects.ShouldSmoke(true,0,2,2,800,1,false),"Smoke requires actual powered contact slip/excess wheel speed");
  var bad=new WorkshopSetup{rideHeightMm=-20};Reject(()=>ChassisTuning.Validate(c,b,bad),"Cannot adjust locked stock suspension");var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string dir=Path.GetFullPath("Verification/Chassis/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,"v5.json");var store=new RaceProgressStore(path,route);for(int i=0;i<40;i++)store.Settle(Finish(route),out _);foreach(var slot in new[]{"differential","suspension","gearing","aero"})for(int stage=1;stage<=3;stage++){var o=c.Find(slot+"_"+stage);store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),o.id,o.price,out _);}int credits=store.Profile.availableCredits;var setup=new WorkshopSetup{rideHeightMm=-20,springPercent=110,damperPercent=105,rollPercent=115,diffLockPercent=80,finalDrivePercent=110,gear1Percent=105,wingPercent=80};string request=Guid.NewGuid().ToString("N");store.SaveWorkshopSetup(request,setup,out bool duplicate);Check(!duplicate&&store.Profile.availableCredits==credits,"Free setup saves atomically without changing cash");store.SaveWorkshopSetup(request,setup,out duplicate);Check(duplicate&&store.Profile.availableCredits==credits,"Setup request retry idempotent");var reloaded=new RaceProgressStore(path,route);Check(reloaded.Profile.version==5&&reloaded.Profile.workshop.setup.rideHeightMm==-20&&reloaded.Profile.workshop.aeroStage==3,"Hardware and adjustment values persist together");var tuned=c.Resolve(reloaded.Profile.workshop);Check(tuned.massKg==stock.massKg+22&&Mathf.Abs(tuned.finalDrive/stock.finalDrive-1.1f)<.0001f,"Aero mass and final drive enter actual powertrain definition");Check(tuned.PeakKw()==stock.PeakKw(),"Chassis tuning cannot fabricate crank power");var invalid=ChassisTuning.Copy(setup);invalid.gear2Percent=20;Reject(()=>ChassisTuning.Validate(c,store.Profile.workshop,invalid),"Invalid ratios rejected");string frozen=File.ReadAllText(path);var fault=new RaceProgressStore(path,route,()=>{throw new IOException("Injected setup save failure");});setup.diffLockPercent=81;Reject(()=>fault.SaveWorkshopSetup(Guid.NewGuid().ToString("N"),setup,out _),"Failed setup write rejected");Check(File.ReadAllText(path)==frozen,"Failed setup changes neither saved build nor receipts");
  string old=Path.GetFullPath("../../artifacts/qa/M14-T02/final-player/isolated-v4.json");if(!File.Exists(old))throw new Exception("Historical v4 fixture missing");string original=File.ReadAllText(old);var migrated=new RaceProgressStore(Path.Combine(dir,"imported-v5.json"),route,legacyFile:old);Check(migrated.Profile.version==5&&migrated.Profile.workshop.induction=="roots"&&migrated.Profile.workshop.inductionStage==3,"Actual prior-release v4 paid multi-stage build imports to v5");Check(File.ReadAllText(old)==original&&migrated.Profile.workshop.setup.finalDrivePercent==100,"Prior v4 remains byte-unchanged; default setup retained");
  var mode=Physics.simulationMode;try{Physics.simulationMode=SimulationMode.Script;EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Driving/Scenes/Finch_HandlingTest.unity");foreach(var model in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(model.gameObject);
   var full=Launch("car_finch",0,1);var tires=Launch("car_finch",3,1);var gentle=Launch("car_finch",0,.45f);Check(full.slip>2.5f&&full.burn>0,"Powerful stock-tire launch produces physical wheelspin/burnout");Check(tires.integral<full.integral,"Track tires reduce measured launch slip energy");Check(gentle.integral<full.integral,"Gentler throttle reduces measured launch slip energy");
  }finally{Physics.simulationMode=mode;}
  File.WriteAllLines("Verification/Chassis/results.txt",lines);
 }catch(Exception e){lines.Add(e.ToString());File.WriteAllLines("Verification/Chassis/results.txt",lines);throw;}}
 struct LaunchResult{public float slip,burn,integral;}
 static LaunchResult Launch(string id,int tires,float pedal){var c=WorkshopCatalog.Load(id);var b=new WorkshopBuild();foreach(var o in c.MissingPath(b,c.Find("induction_roots_3")))c.Apply(b,o);b.tireStage=tires;
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.position=new Vector3(10,.35f,0);var car=g.AddComponent<FinchVehicle>();car.Initialize();car.externalInput=true;car.playerInput=false;car.InstallPowertrain(c.Resolve(b),2);car.forwardGrip=1.15f*c.car.gripModifiers[tires];car.lateralGrip=1.1f*c.car.gripModifiers[tires];ChassisTuning.ApplyVehicle(c,b,car);Physics.SyncTransforms();for(int i=0;i<150;i++){car.Tick(.02f);Physics.Simulate(.02f);}Check(car.GroundedWheels==4&&car.SpeedKph<.5f,"Launch fixture settles on four contacts");car.commandedPedal=pedal;var result=new LaunchResult();for(int i=0;i<300;i++){car.Tick(.02f);Physics.Simulate(.02f);result.slip=Mathf.Max(result.slip,car.DrivenWheelSlip);result.integral+=car.DrivenWheelSlip*.02f;if(car.IsBurningOut)result.burn+=.02f;}lines.Add("MEASURE tires="+tires+" pedal="+pedal+" max excess="+result.slip.ToString("F2")+"m/s slip integral="+result.integral.ToString("F2")+" burnout="+result.burn.ToString("F2")+"s speed="+car.SpeedKph.ToString("F1"));UnityEngine.Object.DestroyImmediate(g);return result;
 }
 public static void Release(){Run();WorkshopVerification.Release();}
}
}
